<?php $pageTitle=$pageTitle??'Data';require __DIR__.'/../partials/header.php';require __DIR__.'/../partials/sidebar.php';?><main class="main"><div class="container-fluid"><?php require __DIR__.'/../partials/navbar.php';?><div class="card-shell"><div class="toolbar"><form><input type="hidden" name="page" value="<?=$this->view?>"><input name="q" class="form-control" placeholder="Cari data..." value="<?=e($_GET['q']??'')?>"></form><a class="btn btn-primary" href="?page=<?=$this->view?>/create">Tambah</a></div><div class="table-responsive"><table class="table align-middle"><thead><tr><?php if($this->view==='produk'):?><th>Gambar</th><?php endif;?><?php foreach($this->fields as $k=>$v):?><th><?=e($v)?></th><?php endforeach;?><th>Aksi</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><?php if($this->view==='produk'):?><td><?php if(!empty($r['gambar'])):?><img src="uploads/products/<?=e($r['gambar'])?>" style="width:48px;height:48px;object-fit:cover;border-radius:10px" alt="gambar produk"><?php else:?><span>-</span><?php endif;?></td><?php endif;?><?php foreach($this->fields as $k=>$v):?><td><?php if($k==='harga'):?><?=rupiah($r[$k])?><?php elseif($this->view==='produk'&&$k==='kategori_id'):?><?=e($r['kategori_nama']??'-')?><?php elseif($this->view==='produk'&&$k==='supplier_id'):?><?=e($r['supplier_nama']??'-')?><?php else:?><?=e($r[$k])?><?php endif;?></td><?php endforeach;?><td><a class="btn btn-sm btn-light" href="?page=<?=$this->view?>/edit&id=<?=$r['id']?>"><i class="bi bi-pencil"></i></a> <a class="btn btn-sm btn-light text-danger" href="?page=<?=$this->view?>/delete&id=<?=$r['id']?>" onclick="return confirm('Hapus data ini?')"><i class="bi bi-trash"></i></a></td></tr><?php endforeach;?></tbody></table></div><div class="d-flex justify-content-between mt-3"><small>Halaman <?=$page?> dari <?=$pages?> · <?=$total?> data</small><?php if($pages>1):?><nav><ul class="pagination mb-0"><li class="page-item"><a class="page-link" href="?page=<?=$this->view?>&p=<?=$page-1?>&q=<?=urlencode($q)?>">‹</a></li><?php for($n=1;$n<=$pages;$n++):?><li class="page-item <?=$n===$page?'active':''?>"><a class="page-link" href="?page=<?=$this->view?>&p=<?=$n?>&q=<?=urlencode($q)?>"><?=$n?></a></li><?php endfor;?><li class="page-item"><a class="page-link" href="?page=<?=$this->view?>&p=<?=$page+1?>&q=<?=urlencode($q)?>">›</a></li></ul></nav><?php endif;?></div></div></div><?php require __DIR__.'/../partials/footer.php';?>
